/// 职业技能库 —— 领域模型与数据（与 UI 原型 `MINDS` / `SKILLS` 一致）。
///
/// 十三大门派各自拥有七本心法（`MINDS`），每本心法下有若干门绝技
/// （`SKILLS`，第 5 位为心法序号）。技能按 心法序号 分组展示。
/// 昆仑（2026-10-23 上线）的七本心法与 24 门技能于 2026-11-13 依据游戏内
/// 「门派技能介绍」页截图补齐（光 / 影双卷 + 五本传统心法）。
library;

import 'package:flutter/foundation.dart';

/// 一本心法。
@immutable
class JobMind {
  const JobMind({required this.name, required this.desc});

  final String name;

  /// 心法一句话说明（如 吸纳内力，化为己用）。
  final String desc;
}

/// 一门技能。
@immutable
class JobSkill {
  const JobSkill({
    required this.name,
    required this.type,
    required this.cd,
    required this.desc,
    required this.mind,
  });

  /// 技能名（如 北冥神功）。
  final String name;

  /// 类型（主动 / 攻击 / 身法 …，决定 tag 配色）。
  final String type;

  /// 冷却（如 30s / —）。
  final String cd;

  /// 技能描述。
  final String desc;

  /// 所属心法序号（对应 `kJobMinds` 下标）。
  final int mind;
}

// 以下数据表为人工紧凑排版（一行一个门派 / 一条记录），便于对照官方资料
// 核对与增改，故豁免 dart format 的 80 列展开。
// dart format off

